class Solution {
public:
    int minLengthAfterRemovals(vector<int>& nums) {
        int n = nums.size();
        int maxFreq = 1, cur = 1;
        for (int i = 1; i < n; ++i) {
            if (nums[i] == nums[i - 1]) {
                ++cur;
                if (cur > maxFreq) maxFreq = cur;
            } else {
                cur = 1;
            }
        }
        return max(n % 2, 2 * maxFreq - n);
    }
};
